end
function F.hitDmg() return F.power() end
function F.cooldown() return ((GC and GC.SwingCooldown) or 0.9) / math.max(1, M.num(lp:GetAttribute("SwingMult"))) + 0.12 end
function F.reach() return (GC and GC.SwingReach) or 10 end
function F.eggOk(e)
    if not (e.PrimaryPart and e.Parent) or e:GetAttribute("Hatching") then return false end
    if os.clock() < (F.eggBack[e] or 0) then return false end
    if anyPicked("f_eggrar") and not picked("f_eggrar", tostring(e:GetAttribute("Rarity"))) then return false end
    local zone = val("f_zone", "Best Zone")
    local z = M.num(e:GetAttribute("ZoneId"))
    if zone ~= "Best Zone" and tostring(z) ~= zone:match("%d+") then return false end
    if zone == "Best Zone" and not F.zoneOk(z) then return false end
