        if F.eggOk(e) then
            local z = M.num(e:GetAttribute("ZoneId"))
            local d = (e.PrimaryPart.Position - r.Position).Magnitude
            if not best or z > bz or (z == bz and d < bd) then best, bz, bd = e, z, d end
        end
    end
