function F.petOk(p, mine)
    local pp = p:FindFirstChild("StealPrompt", true)
    if not (pp and pp.Enabled and p.Parent) then return false end
    if os.clock() < (F.petBack[p] or 0) then return false end
    local r = M.hrp()
    if not r then return false end
    local d = (p:GetPivot().Position - r.Position).Magnitude
    local h = M.hum()
    local speed = math.max(10, h and h.WalkSpeed or 16)
    if M.num(p:GetAttribute("ExpireAt")) - M.now() < d / speed + 3 then return false end
    local z = F.petZone(p)
    if z > 1 and not F.zoneOk(z) and not on("f_heavy") then F.petBack[p] = os.clock() + 30 return false end
    if on("f_waitguard") and F.guardNear(p:GetPivot().Position, 45) then F.petBack[p] = os.clock() + 1.5 return false end
    if mine then return true end
    if anyPicked("f_petrar") and not picked("f_petrar", tostring(p:GetAttribute("Rarity"))) then return false end
    return M.num(p:GetAttribute("Income")) >= M.parse(val("f_minincome", "0"))
end
function F.pickPet()
