        local again = f:FindFirstChild(F.lost.name)
        if again and again:GetAttribute("StolenFrom") then
            F.petBack[again] = nil
            if F.petOk(again, true) then return again end
        end
    end
    local best, bs
    for _, p in ipairs(f:GetChildren()) do
        if F.petOk(p) then
            local d = (p:GetPivot().Position - r.Position).Magnitude
            local s = M.num(p:GetAttribute("Income")) / (d + 60)
