    M.walk(p:GetPivot().Position, function()
        return p.Parent == nil or not pp.Enabled or (p:GetPivot().Position - M.hrp().Position).Magnitude < 5
    end, 25)
    if not (p.Parent and pp.Enabled) then return false end
    local r = M.hrp()
    if (p:GetPivot().Position - r.Position).Magnitude > pp.MaxActivationDistance - 1 then return false end
