    return false
end
function F.crack(e)
    M.equipHammer()
    local pos = e.PrimaryPart.Position
    S.task = __T["Cracking "] .. tostring(e:GetAttribute("EggName") or e.Name)
    local reach = F.reach() + e.PrimaryPart.Size.X / 2 - 1.5
    M.walk(pos, function() return not e.Parent or M.flat(pos, M.hrp().Position) <= reach - 1 end, 25)
    if not e.Parent then return false end
    if M.flat(pos, M.hrp().Position) > reach then F.eggBack[e] = os.clock() + 20 return false end
    M.stop()
    local before = {}
    local wild = F.folder("WildPets")
    if wild then for _, p in ipairs(wild:GetChildren()) do before[p] = true end end
    local t0 = os.clock()
    local last = M.num(e:GetAttribute("HP"))
    local miss = 0
    while e.Parent and not e:GetAttribute("Hatching") and os.clock() - t0 < 45 do
        if not (RUNNING and on("f_crack") and M.alive()) or on("f_pause") then return false end
        if M.flat(pos, M.hrp().Position) > reach then M.walk(pos, function() return M.flat(pos, M.hrp().Position) <= reach - 1 end, 6) end
        M.dismount()
        M.equipHammer()
        A.fire("HitEgg", e)
        task.wait(F.cooldown())
        local hp = M.num(e:GetAttribute("HP"))
        if hp < last then miss = 0 else miss = miss + 1 end
        last = hp
        if miss >= 5 then F.eggBack[e] = os.clock() + 30 LOG("egg stuck", e.Name, hp) return false end
    end
    if not (e.Parent and e:GetAttribute("Hatching")) and e.Parent then F.eggBack[e] = os.clock() + 30 return false end
    S.cracked = S.cracked + 1
    S.task = __T["Waiting for it to hatch"]
    local t1 = os.clock()
    while os.clock() - t1 < 20 do
        if not (RUNNING and on("f_crack")) or on("f_pause") then return true end
        if wild then
            for _, p in ipairs(wild:GetChildren()) do
                if not before[p] and (p:GetPivot().Position - pos).Magnitude < 70 and F.petOk(p, true) then
                    if F.grab(p) then F.bank() end
                    return true
                end
            end
        end
        task.wait(0.2)
    end
    return true
end
