function F.mergeGroups()
    local need = (GC and GC.MergeCount) or 3
    local by = {}
    for _, p in ipairs(P.list) do
        local mut = type(p) == "table" and (p.Mut or p.Mutation)
        if type(p) == "table" and not p.Active and p.Uid and p.Id and not (mut and mut ~= "None" and mut ~= "") then
            local rar = P.rarity(p.Id)
            if not (rar and picked("m_keep", rar)) then
                by[p.Id] = by[p.Id] or {}
                table.insert(by[p.Id], p.Uid)
            end
        end
    end
    local out = {}
    for id, uids in pairs(by) do
        while #uids >= need do
            local g = {}
            for _ = 1, need do g[#g + 1] = table.remove(uids, 1) end
            out[#out + 1] = { id = id, uids = g }
        end
    end
    return out
end
function F.merge()
    if not F.due("merge") then return false end
    F.back.merge = os.clock() + 45
    if os.clock() - P.at > 5 then P.sync() task.wait(0.8) end
    local groups = F.mergeGroups()
    if #groups == 0 then return false end
    local fp = F.fuse()
    if not fp then return false end
    S.task = __T["Merging pets"]
    M.walk(fp, function() return M.flat(fp, M.hrp().Position) < 10 end, 30)
    if M.flat(fp, M.hrp().Position) > 13 then return true end
    for i, g in ipairs(groups) do
        if i > 6 or M.cancelled() then break end
        local ok, msg = A.invoke("PetAction", "Merge", g.uids)
        LOG("merge", g.id, ok, msg)
        if ok then S.merged = (S.merged or 0) + 1 else break end
        task.wait(0.4)
    end
    P.at = 0
    F.back.place = 0
    return true
end
function F.unplacedEggs()
