function F.placeEggs()
    if not F.due("place") then return false end
    F.back.place = os.clock() + 30
    local list = F.unplacedEggs()
    if #list == 0 then return false end
    local home, p = M.home(), M.plot()
    if not (home and p and p:FindFirstChild("Base")) then return false end
    S.task = __T["Placing eggs"]
    M.walk(home, function() return M.flat(home, M.hrp().Position) < 12 end, 30)
    M.dismount()
    local cf, size = p.Base:GetBoundingBox()
    local spots = {}
    for x = -2, 2 do for z = -2, 2 do spots[#spots + 1] = Vector3.new(x * 7, 0, z * 7) end end
    local si = 1
    for _, uid in ipairs(list) do
        local done = false
        while si <= #spots and not done do
            local off = spots[si]
            si = si + 1
            local ok, msg = A.invoke("PetAction", "Place", { Uid = uid, Pos = Vector3.new(cf.X + off.X, cf.Y + size.Y / 2, cf.Z + off.Z), Yaw = 0 })
            LOG("place egg", uid, ok, msg)
            if ok then done = true S.placed = (S.placed or 0) + 1 end
            if tostring(msg):find("full") then F.back.place = os.clock() + 300 return true end
            if tostring(msg):find("closer") then return true end
        end
    end
    P.at = 0
    return true
end
