        return
    end
    local best, bp
    for _, a in ipairs(list) do if owned[a.Id] and (not bp or M.num(a.Power) > bp) then best, bp = a, M.num(a.Power) end end
    if best and lp:GetAttribute("EquippedAsarol") ~= best.Id then A.invoke("AsarolShop", "Equip", best.Id) end
