    local list = B.list(GC and GC.Trails)
    local bestOwned
    for _, t in ipairs(list) do if owned[t.Id] and (not bestOwned or M.num(t.Mult) > M.num(bestOwned.Mult)) then bestOwned = t end end
    if bestOwned and M.num(bestOwned.Mult) > cur and lp:GetAttribute("EquippedTrail") ~= bestOwned.Id then
        local ok = A.invoke("TrailShop", "Equip", bestOwned.Id)
        LOG("trail equip", bestOwned.Id, ok)
        if not ok then B.back.trail = os.clock() + 30 end
        return
    end
    local pick
    for _, t in ipairs(list) do
        if not owned[t.Id] and M.num(t.Mult) > cur and t.Price <= M.spend() and (not pick or M.num(t.Mult) > M.num(pick.Mult)) then pick = t end
