function B.sell()
    local free = M.num(lp:GetAttribute("PetStorageFree"))
    if free > val("s_free", 3) then return end
    if os.clock() - P.at > 5 then P.sync() task.wait(0.6) end
    local worst, wi
    for _, p in ipairs(P.list) do
        local mut = type(p) == "table" and (p.Mut or p.Mutation)
        if type(p) == "table" and not p.Active and p.Uid and not (mut and mut ~= "None" and mut ~= "") then
            local rar = P.rarity(p.Id)
            if not (rar and picked("s_keep", rar)) then
                local inc = P.income(p)
                if not wi or inc < wi then worst, wi = p, inc end
            end
        end
    end
    if worst then
        local ok, msg = A.invoke("PetAction", "Sell", { worst.Uid })
        LOG("sell", worst.Id, ok, msg)
        if ok then S.sold = S.sold + 1 P.at = 0 else B.back.sell = os.clock() + 30 end
    end
end
function B.growAll()
    local at = M.num(P.data and P.data.GrowAllAt)
    if at > M.now() then B.back.grow = os.clock() + math.min(600, at - M.now() + 2) return end
    local eggs = P.data and P.data.Eggs
    local any = false
    if type(eggs) == "table" then for _, e in pairs(eggs) do if type(e) == "table" and e.Active then any = true end end end
    if not any then B.back.grow = os.clock() + 60 return end
    local ok, msg = A.invoke("PetAction", "GrowAll")
    LOG("growall", ok, msg)
    local mins = tonumber(tostring(msg):match("Ready in (%d+) min"))
    B.back.grow = os.clock() + (ok and 600 or (mins and mins * 60 + 5 or 300))
end
function B.bat()
    local claimed = {}
    for n in tostring(lp:GetAttribute("IndexClaims") or ""):gmatch("%d+") do claimed[tonumber(n)] = true end
    local best
    for _, b in ipairs((GC and GC.Bats) or {}) do
        if type(b) == "table" and b.Id and (not b.Zone or claimed[b.Zone]) and not (B.badBat and B.badBat[b.Id]) and (not best or M.num(b.Knockback) > M.num(best.Knockback)) then best = b end
    end
    if best and lp:GetAttribute("EquippedBat") ~= best.Id then
        local ok, msg = A.invoke("BatAction", "Equip", best.Id)
        LOG("bat", best.Id, ok, msg)
        if not ok then B.badBat = B.badBat or {} B.badBat[best.Id] = true end
        B.back.bat = os.clock() + 60
    else
        B.back.bat = os.clock() + 30
    end
end
function B.useMut()
    local tool
    for _, t in ipairs(lp.Backpack:GetChildren()) do if t:IsA("Tool") and t:GetAttribute("MutItem") then tool = t break end end
    local ch = lp.Character
    if not tool and ch then local cur = ch:FindFirstChildOfClass("Tool") if cur and cur:GetAttribute("MutItem") then tool = cur end end
    if not tool then return false end
    if os.clock() - P.at > 3 then P.sync() task.wait(0.8) end
    local best, bi
    for _, p in ipairs(P.list) do
        local mut = type(p) == "table" and (p.Mut or p.Mutation)
        if type(p) == "table" and p.Active and not (mut and mut ~= "None" and mut ~= "") then
            local inc = P.income(p)
            if not bi or inc > bi then best, bi = p, inc end
        end
    end
    if not best then return false end
    M.manual = true
    local h = M.hum()
    if h and tool.Parent ~= ch then h:EquipTool(tool) task.wait(0.4) end
    local ok, msg = A.invoke("UndasShop", "Use", tool:GetAttribute("MutItem"), best.Uid)
    M.manual = false
    LOG("potion use", best.Id, tool:GetAttribute("MutItem"), ok, msg)
    if ok then S.mutated = (S.mutated or 0) + 1 end
    P.at = 0
    return true
end
function B.potion()
    if B.useMut() then B.back.potion = os.clock() + 3 return end
    local us = GC and GC.UndasShop
    if F.speed() < M.num(us and us.MinSpeed) then B.back.potion = os.clock() + 60 return end
    local al = GC and GC.Albularyo
    local agimat = M.num(lp:GetAttribute("Agimat"))
    for _, it in ipairs(B.stock()) do
        if (picked("m_pots", it.id) or not anyPicked("m_pots")) and it.price <= agimat then
            local slot
            for si, sl in ipairs((al and al.Slots) or {}) do for _, id in ipairs(sl.Pool or {}) do if id == it.id then slot = si end end end
            if slot then
                local ok, msg = A.invoke("Albularyo", "Buy", slot, it.id)
                LOG("potion buy", slot, it.id, ok, msg)
                if ok then B.back.potion = os.clock() + 2 return end
            end
        end
    end
    B.back.potion = os.clock() + 120
end
function B.openEggs()
    local eggs = P.data and P.data.Eggs
    B.back.open = os.clock() + 15
    if type(eggs) ~= "table" then return end
    local now = M.now()
    for _, e in pairs(eggs) do
        if type(e) == "table" and e.Active and e.Uid and M.num(e.ReadyAt) > 0 and M.num(e.ReadyAt) <= now then
            local ok, msg = A.invoke("PetAction", "HatchEgg", e.Uid)
            LOG("open egg", e.Uid, ok, msg)
            if ok then S.opened = (S.opened or 0) + 1 P.at = 0 end
            B.back.open = os.clock() + 2
            return
        end
    end
end
function B.zoneDone(z)
    local idx = P.data and P.data.Index
    if type(idx) ~= "table" then return false end
    local any = false
    for _, p in pairs((GC and GC.Pets) or {}) do
        if type(p) == "table" and p.Zone == z and p.Id then
            any = true
            if not idx[p.Id] then return false end
        end
    end
    return any
end
function B.stock()
    local out = {}
    local pg = lp:FindFirstChildOfClass("PlayerGui")
    local g = pg and pg:FindFirstChild("AlbularyoShopGui")
    local list = g and g:FindFirstChild("List", true)
    if not list then return out end
    for _, row in ipairs(list:GetChildren()) do
        local body = row:FindFirstChild("Body")
        local lbl = body and body:FindFirstChild("Buy") and body.Buy:FindFirstChild("Label", true)
        local left = body and body:FindFirstChild("StatBar") and body.StatBar:FindFirstChild("Stat")
        if lbl then
            local txt = tostring(lbl.Text):gsub("<[^>]+>", "")
            local n = M.parse(txt)
            local lt = left and tonumber((tostring(left.Text):gsub("<[^>]+>", "")):match("(%d+) left")) or 1
            if n > 0 and lt > 0 then out[#out + 1] = { id = row.Name, price = n } end
        end
    end
    return out
end
function B.codesRun()
