    local groups = {
        { __T["Farm"], { "+ Auto crack baluts", "+ Best zone or pick", "+ Egg rarity filter", "+ Grab wild pets", "+ Wait for guards (toggle)", "+ Train on trisikad", "+ Grab heavy pets", "+ Pet rarity filter", "+ Min income filter", "+ Grab Agimat drops", "+ Auto bring home", "+ Re-grab dropped", "+ Dodge guards", "+ Auto equip best" } },
        { __T["Shop"], { "+ Auto best hammer", "+ Auto best trail", "+ Best bat", "+ Auto merge dupes", "+ Auto place eggs", "+ Auto grow all", "+ Auto open eggs", "+ Auto potions", "+ Auto pen upgrade", "+ Auto trisikad upgrade", "+ Auto sell spares", "+ Keep rarities", "+ Index rewards", "+ Auto codes", "+ Offline cash", "+ Keep cash" } },
        { "Player", { "+ Anti knockback", "+ Anti AFK", "+ Rejoin / server hop", "+ Join lowest server" } },
        { "Other", { "+ Streamer mode", "+ Executor check" } },
    }
    for _, g in ipairs(groups) do
        CG:AddLabel('<b>' .. g[1] .. '</b>', true)
        for _, l in ipairs(g[2]) do CG:AddLabel(l, true) end
    end
end)
